/**
 * Formenbibliothek fuer die Symbolbilder.
 *
 * Jede Form ist eine kleine Linienzeichnung in lokalen Koordinaten: Anthrazit
 * auf Weiss, Flaechen weiss oder sehr helles Grau, Bordeaux nur als kleiner
 * Akzent. Stehende Gegenstaende haben ihren Ursprung unten in der Mitte
 * (Bodenkontakt bei y = 0), schwebende Zeichen in der Mitte.
 *
 * Die Szenen in lib-motiv-szenen.mjs setzen diese Formen zusammen. Zwei Motive
 * gelten als verschieden, wenn ihre Elementfolge verschieden ist; deshalb
 * traegt jede Form ihre eigene, feste Elementfolge (docs/SYMBOLBILDER-ANFORDERUNG.md).
 */

export const FARBE = {
  kontur: '#2b2926',   // Anthrazit, Zeichnung
  flaeche: '#ffffff',  // Weiss
  grau: '#e9e6df',     // helles Grau, Nebenflaechen
  boden: '#f3f1ec',    // sehr helles Grau, Bodenband
  marke: '#971725',    // Bordeaux, ein Akzent je Motiv
  meta: '#615d55',
};
const K = FARBE.kontur, W = FARBE.flaeche, G = FARBE.grau, M = FARBE.marke;
export const STRICH = 14;

// Kleine Helfer
const r = (x, y, w, h, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" ${extra}/>`;
const rr = (x, y, w, h, rad, extra = '') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rad}" ${extra}/>`;
const c = (cx, cy, rad, extra = '') => `<circle cx="${cx}" cy="${cy}" r="${rad}" ${extra}/>`;
const el = (cx, cy, rx, ry, extra = '') => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" ${extra}/>`;
const l = (x1, y1, x2, y2, extra = '') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${extra}/>`;
const p = (d, extra = '') => `<path d="${d}" ${extra}/>`;
const pl = (pts, extra = '') => `<polyline points="${pts}" fill="none" ${extra}/>`;
const pg = (pts, extra = '') => `<polygon points="${pts}" ${extra}/>`;
const fG = `fill="${G}"`, fW = `fill="${W}"`, fM = `fill="${M}"`, fK = `fill="${K}"`, fN = 'fill="none"';
const ohne = 'stroke="none"';
const duenn = `stroke-width="${STRICH * 0.6}"`;

// --------------------------------------------------------------- Szene
export const SZENE = {
  /** Bodenband unter y = 700 mit Horizontlinie. */
  boden: () => r(0, 700, 1600, 200, `fill="${FARBE.boden}" ${ohne}`) + l(0, 700, 1600, 700),
  /** Nur eine Horizontlinie, kein Band. */
  horizont: () => l(0, 700, 1600, 700),
  /** Angedeuteter Innenraum: Fussbodenlinie plus Sockelleiste. */
  innen: () => r(0, 700, 1600, 200, `fill="${FARBE.boden}" ${ohne}`) + l(0, 700, 1600, 700) + l(0, 660, 1600, 660, duenn),
  /** Kleine Beschriftung unten rechts. */
  marke: () => `<text x="1540" y="862" text-anchor="end" font-family="Inter,Arial,sans-serif" font-size="26" letter-spacing="3" fill="${FARBE.meta}" ${ohne}>SYMBOLBILD</text>`,
};

